}

export function requireIdempotencyKey(headers: Record<string, string | undefined>): string {
  const key = headers['idempotency-key']?.trim();
  if (!key || key.length > 128) throw new Error('invalid idempotency key');
  return key;
}

import { CheckoutService, RetryableCheckoutRequest } from '../../../packages/checkout/src';

export class RetryCheckoutWorker {
  constructor(private readonly checkout: CheckoutService) {}

  run(request: RetryableCheckoutRequest) {
    return this.checkout.place(request);
  }
}

import { CheckoutAttempt } from './checkout-attempt';

export class CheckoutAttemptRepository {
  private readonly values: CheckoutAttempt[] = [];

  start(attempt: CheckoutAttempt): void {
    this.values.push(attempt);
  }

  finish(id: string, state: 'rejected' | 'completed', reason?: string): void {
    const attempt = this.values.find((candidate) => candidate.id === id);
    if (!attempt) throw new Error('checkout attempt not found');
    attempt.state = state;
    attempt.reason = reason;
  }

  all(): CheckoutAttempt[] {
    return this.values.map((attempt) => ({ ...attempt }));
  }
}

export interface CheckoutAttempt {
  id: string;
  tenantId: string;
  idempotencyKey?: string;
  state: 'started' | 'rejected' | 'completed';
  reason?: string;
}

import { PlaceOrderInput } from './checkout-service';

export interface RetryableCheckoutRequest extends PlaceOrderInput {
  idempotencyKey: string;
}

export function requestFingerprint(input: PlaceOrderInput): string {
  return JSON.stringify([
    input.customerId,
    input.sku,
    input.quantity,
    input.unitPriceCents,
    input.promotionBps,
  ]);
}

