export interface OrderFilters {
  state?: 'paid' | 'cancelled';
  minimumTotalCents?: number;
}

export class OrderQueryService {
  constructor(private readonly orders: OrderRepository) {}

  list(tenantId: string, filters: OrderFilters = {}): OrderListItem[] {
    return this.orders
      .forTenant(tenantId)
      .filter((order) => !filters.state || order.state === filters.state)
      .filter((order) => filters.minimumTotalCents === undefined || order.totalCents >= filters.minimumTotalCents)
      .sort((left, right) => right.placedAt - left.placedAt)
      .map(toOrderListItem);
  }
}

import { Order } from './order';

export interface OrderListItem {
  id: string;
  customerId: string;
  sku: string;
  quantity: number;
  totalCents: number;
  state: Order['state'];
  placedAt: number;
}

export function toOrderListItem(order: Order): OrderListItem {
  return {
    id: order.id,
    customerId: order.customerId,
    sku: order.sku,
    quantity: order.quantity,
    totalCents: order.totalCents,
    state: order.state,
    placedAt: order.placedAt,
  };
}

forTenant(tenantId: string): Order[] {
  return this.all().filter((order) => order.tenantId === tenantId);
}

import { OrderListItem } from './order-read-model';

export interface OrderSummary {
  orderCount: number;
  paidCount: number;
  cancelledCount: number;
  paidRevenueCents: number;
}

export function summarizeOrders(orders: OrderListItem[]): OrderSummary {
  return {
    orderCount: orders.length,
    paidCount: orders.filter((order) => order.state === 'paid').length,
    cancelledCount: orders.filter((order) => order.state === 'cancelled').length,
    paidRevenueCents: orders
      .filter((order) => order.state === 'paid')
      .reduce((total, order) => total + order.totalCents, 0),
  };
}

import { Inventory } from '../../catalog/src';
import { Clock, IdSource, TenantId } from '../../core/src';
import { Outbox } from '../../fulfillment/src/outbox';
import { OrderRepository } from './order-repository';
import { PaymentGateway } from './payment';
import { price } from './pricing';

export interface PlaceOrderInput {
  tenantId: TenantId;
  customerId: string;
  sku: string;
  quantity: number;
  unitPriceCents: number;
  promotionBps: number;
}

export type PlaceOrderResult =
  | { ok: true; orderId: string; totalCents: number }
  | { ok: false; reason: string };

export class CheckoutService {
  constructor(
    private readonly inventory: Inventory,
    private readonly payments: PaymentGateway,
    private readonly orders: OrderRepository,
    private readonly outbox: Outbox,
    private readonly clock: Clock,
    private readonly ids: IdSource,
  ) {}

  place(input: PlaceOrderInput): PlaceOrderResult {
    const total = price(input);
    const reservationId = this.ids.next('reservation');
    const reservation = this.inventory.reserve({
      id: reservationId,
      sku: input.sku,
      quantity: input.quantity,
      expiresAt: this.clock.now() + 15 * 60_000,
    });
    if (!reservation) return { ok: false, reason: 'insufficient_stock' };

    const paymentId = this.ids.next('payment');
    const charge = this.payments.charge({ paymentId, tenantId: input.tenantId, amountCents: total.totalCents });
    if (!charge.ok) {
      this.inventory.release(reservationId);
      return charge;
    }

    const orderId = this.ids.next('order');
    const eventId = this.ids.next('event');
    this.inventory.commit(reservationId);
    this.orders.save({
      id: orderId,
      tenantId: input.tenantId,
      customerId: input.customerId,
      sku: input.sku,
      quantity: input.quantity,
      totalCents: total.totalCents,
      paymentId,
      reservationId,
      eventId,
      state: 'paid',
    });
    this.outbox.append({ id: eventId, type: 'order.placed', occurredAt: this.clock.now(), payload: { orderId } });
    return { ok: true, orderId, totalCents: total.totalCents };
  }
}

    private readonly orders: OrderRepository,
    private readonly outbox: Outbox,
    private readonly clock: Clock,
    private readonly ids: IdSource,
    private readonly idempotency: IdempotencyRepository,
    private readonly attempts: CheckoutAttemptRepository,
  ) {}

  place(input: PlaceOrderInput): PlaceOrderResult {
    if (input.idempotencyKey) {
      const existing = this.idempotency.find(input.tenantId, input.idempotencyKey);
      if (existing) {
        if (existing.requestFingerprint !== requestFingerprint(input)) {
          throw new IdempotencyConflict(input.idempotencyKey);
        }
        return existing.result;
      }
    }
    const attemptId = this.ids.next('attempt');
    this.attempts.start({
      id: attemptId,
      tenantId: input.tenantId,
      idempotencyKey: input.idempotencyKey,
      state: 'started',
    });
    const total = price(input);
    const reservationId = this.ids.next('reservation');
    const reservation = this.inventory.reserve({
      id: reservationId,
      sku: input.sku,
      quantity: input.quantity,
      expiresAt: this.clock.now() + 15 * 60_000,
    });
    if (!reservation) {
      this.attempts.finish(attemptId, 'rejected', 'insufficient_stock');
      return { ok: false, reason: 'insufficient_stock' };
    }

    const paymentId = this.ids.next('payment');
    const charge = this.payments.charge({ paymentId, tenantId: input.tenantId, amountCents: total.totalCents });
    if (!charge.ok) {
      this.inventory.release(reservationId);
      this.attempts.finish(attemptId, 'rejected', charge.reason);
      return charge;
    }

    const orderId = this.ids.next('order');
    const eventId = this.ids.next('event');
    this.inventory.commit(reservationId);
    this.orders.save({
      id: orderId,
      tenantId: input.tenantId,
      customerId: input.customerId,
      sku: input.sku,
      quantity: input.quantity,
      totalCents: total.totalCents,
      paymentId,
      reservationId,
      eventId,
      placedAt: this.clock.now(),
      state: 'paid',
    });
    this.outbox.append({ id: eventId, type: 'order.placed', occurredAt: this.clock.now(), payload: { orderId } });
    const result = { ok: true as const, orderId, totalCents: total.totalCents };
    this.attempts.finish(attemptId, 'completed');
    if (input.idempotencyKey) {
      this.idempotency.save({
        tenantId: input.tenantId,
        key: input.idempotencyKey,
        requestFingerprint: requestFingerprint(input),
        result,
        recordedAt: this.clock.now(),
      });
    }
    return result;
  }
}

import { CheckoutService, PlaceOrderInput } from '../../../packages/checkout/src';
import { Principal, requirePrincipal } from './auth';

export class CheckoutHandler {
  constructor(private readonly checkout: CheckoutService) {}

  handle(principal: Principal | undefined, input: Omit<PlaceOrderInput, 'tenantId'>) {
    const actor = requirePrincipal(principal);
    return this.checkout.place({ ...input, tenantId: actor.tenantId });
  }
}

import { CheckoutService, PlaceOrderInput } from '../../../packages/checkout/src';
import { Principal, requirePrincipal } from './auth';
import { requireIdempotencyKey } from './idempotency-header';

export class CheckoutHandler {
  constructor(private readonly checkout: CheckoutService) {}

  handle(principal: Principal | undefined, input: Omit<PlaceOrderInput, 'tenantId' | 'idempotencyKey'>, headers: Record<string, string | undefined>) {
    const actor = requirePrincipal(principal);
    const idempotencyKey = requireIdempotencyKey(headers);
    return this.checkout.place({ ...input, tenantId: actor.tenantId, idempotencyKey });
  }
}

import { Order } from './order';

export class OrderRepository {
  private readonly orders = new Map<string, Order>();

  save(order: Order): void {
    this.orders.set(order.id, order);
  }

  findForTenant(tenantId: string, orderId: string): Order | undefined {
    const order = this.orders.get(orderId);
    return order?.tenantId === tenantId ? order : undefined;
  }

  all(): Order[] {
    return [...this.orders.values()];
  }
}

import { OrderRepository } from './order-repository';

export function capturedRevenue(orders: OrderRepository): number {
  return orders.all().filter((order) => order.state === 'paid').reduce((sum, order) => sum + order.totalCents, 0);
}
